#!/usr/bin/env bash
set -Eeuo pipefail

if [[ ${EUID} -ne 0 ]]; then
  echo "Run this command with sudo: sudo rf-monitor configure-web" >&2
  exit 1
fi

STATE_FILE="${RFMON_STATE_FILE:-/etc/rf-monitor/install.conf}"
[[ -r "${STATE_FILE}" ]] || { echo "Installation state not found: ${STATE_FILE}" >&2; exit 1; }
# This file is generated by the installer and owned by root.
source "${STATE_FILE}"

RELEASE_DIR="${RFMON_RELEASE_DIR:-${INSTALL_DIR}}"
NGINX_TEMPLATE="${RELEASE_DIR}/deploy/nginx-rf-monitor.conf.template"
NGINX_FILE="/etc/nginx/sites-available/rf-monitor"
TLS_DIR="/etc/rf-monitor/tls"

die() { echo "ERROR: $*" >&2; exit 1; }
say() { printf '\n%s\n' "$*"; }
sed_value() { printf '%s' "$1" | sed -e 's/[&|]/\\&/g'; }

config_value() {
  local key="$1" fallback="$2" line value
  line="$(grep -E "^${key}=" "${CONFIG_FILE}" 2>/dev/null | tail -n 1 || true)"
  [[ -n "${line}" ]] || { printf '%s' "${fallback}"; return; }
  value="${line#*=}"
  if [[ "${value}" == \"*\" && "${value}" == *\" ]]; then value="${value:1:${#value}-2}"; fi
  printf '%s' "${value}"
}

update_state() {
  local key="$1" value="$2" temporary
  temporary="$(mktemp "${STATE_FILE}.XXXXXX")"
  grep -Ev "^${key}=" "${STATE_FILE}" > "${temporary}" || true
  printf '%s=%q\n' "${key}" "${value}" >> "${temporary}"
  install -m 0644 -o root -g root "${temporary}" "${STATE_FILE}"
  rm -f "${temporary}"
}

[[ -f "${NGINX_TEMPLATE}" ]] || die "Nginx template is missing: ${NGINX_TEMPLATE}"
command -v nginx >/dev/null || die "Nginx is not installed. Re-run the RF Monitor installer."
command -v openssl >/dev/null || die "OpenSSL is not installed. Re-run the RF Monitor installer."
command -v python3 >/dev/null || die "Python 3 is required to validate the network range."

detected_ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
[[ -n "${detected_ip}" ]] || detected_ip="rf-monitor.local"
if ip -o -4 address show scope global 2>/dev/null | grep -F " ${detected_ip}/" | grep -qw dynamic; then
  echo "NOTE: ${detected_ip} is assigned by DHCP and may change."
  echo "For reliable remote access, reserve this address in the router or configure a stable DNS name."
fi
current_host="${PUBLIC_URL:-}"
current_host="${current_host#*://}"
current_host="${current_host%%/*}"
current_host="${current_host%%:*}"
if [[ "${current_host}" == "127.0.0.1" || "${current_host}" == "localhost" ]]; then
  current_host="${detected_ip}"
fi
current_host="${current_host:-${detected_ip}}"

say "Secure dashboard network setup"
echo "This wizard publishes only HTTPS port 443. SDRconnect and Node.js remain private."
read -r -p "Dashboard DNS name or IPv4 address [${current_host}]: " server_name
server_name="${server_name:-${current_host}}"
[[ "${server_name}" =~ ^[A-Za-z0-9._-]+$ ]] || die "Use a DNS name or IPv4 address without spaces, a path, or https://."
if [[ "${server_name}" =~ ^[0-9.]+$ ]]; then
  python3 - "${server_name}" <<'PY' >/dev/null || die "Invalid IPv4 address: ${server_name}"
import ipaddress, sys
ipaddress.ip_address(sys.argv[1])
PY
fi

detected_interface_cidr="$(ip -o -4 address show scope global 2>/dev/null | awk -v expected="${detected_ip}" '
{
  cidr = $4
  address = cidr
  sub(/\/.*/, "", address)
  if (address == expected) { print cidr; exit }
}')"
detected_interface_cidr="${detected_interface_cidr:-${detected_ip}/24}"
default_cidr="$(python3 - "${detected_interface_cidr}" <<'PY'
import ipaddress, sys
try:
    print(ipaddress.ip_interface(sys.argv[1]).network)
except ValueError:
    print("")
PY
)"
cidr_default="${OPERATOR_CIDR:-${default_cidr}}"
read -r -p "Operator network allowed to open the dashboard [${cidr_default:-required}]: " operator_cidr
operator_cidr="${operator_cidr:-${OPERATOR_CIDR:-${default_cidr}}}"
[[ -n "${operator_cidr}" ]] || die "An operator network is required, for example 10.20.30.0/24."
normalized_cidr="$(python3 - "${operator_cidr}" <<'PY'
import ipaddress, sys
print(ipaddress.ip_network(sys.argv[1], strict=False))
PY
)" || die "Invalid network range: ${operator_cidr}"
operator_cidr="${normalized_cidr}"

echo
echo "TLS certificate options:"
echo "  1. Generate a private local CA and server certificate (simplest for an isolated LAN)"
echo "  2. Use an existing certificate issued by your organization"
read -r -p "Choose 1 or 2 [1]: " certificate_choice
certificate_choice="${certificate_choice:-1}"

ca_certificate=""
if [[ "${certificate_choice}" == "1" ]]; then
  install -d -m 0700 -o root -g root "${TLS_DIR}"
  ca_key="${TLS_DIR}/rf-monitor-local-ca.key"
  ca_certificate="${TLS_DIR}/rf-monitor-local-ca.crt"
  tls_key="${TLS_DIR}/rf-monitor.key"
  tls_certificate="${TLS_DIR}/rf-monitor.crt"
  openssl_config="${TLS_DIR}/rf-monitor-openssl.cnf"

  if [[ ! -f "${ca_key}" || ! -f "${ca_certificate}" ]]; then
    openssl req -x509 -newkey rsa:3072 -sha256 -nodes -days 3650 \
      -subj "/CN=RF Monitor Local Certificate Authority" \
      -keyout "${ca_key}" -out "${ca_certificate}" >/dev/null 2>&1
  fi

  # Include the chosen address plus safe local aliases. Operators can then use
  # the printed IP or hostname without a certificate-name error.
  san_candidates=("${server_name}" "${detected_ip}" "$(hostname -f 2>/dev/null || true)" "$(hostname -s 2>/dev/null || true)" "$(hostname -s 2>/dev/null || true).local")
  declare -A seen_sans=()
  dns_index=0
  ip_index=0
  san_lines=""
  for candidate in "${san_candidates[@]}"; do
    candidate="${candidate,,}"
    [[ -n "${candidate}" && -z "${seen_sans[${candidate}]:-}" ]] || continue
    seen_sans["${candidate}"]=1
    if python3 - "${candidate}" <<'PY' >/dev/null 2>&1
import ipaddress, sys
ipaddress.ip_address(sys.argv[1])
PY
    then
      ip_index=$((ip_index + 1))
      san_lines+="IP.${ip_index} = ${candidate}"$'\n'
    elif [[ "${candidate}" =~ ^[a-z0-9][a-z0-9.-]*[a-z0-9]$ || "${candidate}" =~ ^[a-z0-9]$ ]]; then
      dns_index=$((dns_index + 1))
      san_lines+="DNS.${dns_index} = ${candidate}"$'\n'
    fi
  done
  cat > "${openssl_config}" <<EOF
[req]
distinguished_name = subject
req_extensions = extensions
prompt = no

[subject]
CN = ${server_name}

[extensions]
subjectAltName = @alternative_names
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth

[alternative_names]
${san_lines}
EOF
  openssl req -new -newkey rsa:3072 -nodes -sha256 \
    -config "${openssl_config}" -keyout "${tls_key}" -out "${TLS_DIR}/rf-monitor.csr" >/dev/null 2>&1
  openssl x509 -req -sha256 -days 825 \
    -in "${TLS_DIR}/rf-monitor.csr" \
    -CA "${ca_certificate}" -CAkey "${ca_key}" -CAcreateserial \
    -extfile "${openssl_config}" -extensions extensions \
    -out "${tls_certificate}" >/dev/null 2>&1
  chmod 0600 "${ca_key}" "${tls_key}"
  chmod 0644 "${ca_certificate}" "${tls_certificate}"
elif [[ "${certificate_choice}" == "2" ]]; then
  read -r -p "Full path to the TLS certificate: " tls_certificate
  read -r -p "Full path to the TLS private key: " tls_key
  [[ -r "${tls_certificate}" ]] || die "Certificate cannot be read: ${tls_certificate}"
  [[ -r "${tls_key}" ]] || die "Private key cannot be read: ${tls_key}"
  openssl x509 -in "${tls_certificate}" -noout >/dev/null 2>&1 || die "The certificate is not valid PEM."
  openssl pkey -in "${tls_key}" -noout >/dev/null 2>&1 || die "The private key is not valid PEM."
else
  die "Choose certificate option 1 or 2."
fi

backend_port="$(config_value RF_MONITOR_PORT 8080)"
sdr_url="$(config_value SDRCONNECT_URL ws://127.0.0.1:5454/)"
sdr_urls="$(config_value SDRCONNECT_URLS "${sdr_url}")"
mapfile -t local_sdr_ports < <("${NODE_BIN}" -e '
  for (const value of process.argv[1].split(",")) {
    const url = new URL(value.trim());
    if (["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)) {
      console.log(url.port || (url.protocol === "wss:" ? "443" : "80"));
    }
  }
' "${sdr_urls}")

sed \
  -e "s|@@SERVER_NAME@@|$(sed_value "${server_name}")|g" \
  -e "s|@@TLS_CERTIFICATE@@|$(sed_value "${tls_certificate}")|g" \
  -e "s|@@TLS_PRIVATE_KEY@@|$(sed_value "${tls_key}")|g" \
  -e "s|@@OPERATOR_CIDR@@|$(sed_value "${operator_cidr}")|g" \
  -e "s|@@BACKEND_PORT@@|$(sed_value "${backend_port}")|g" \
  "${NGINX_TEMPLATE}" > "${NGINX_FILE}"
if [[ -L /etc/nginx/sites-enabled/default \
  && "$(readlink -f /etc/nginx/sites-enabled/default)" == "/etc/nginx/sites-available/default" ]]; then
  rm -f /etc/nginx/sites-enabled/default
fi
ln -sfn "${NGINX_FILE}" /etc/nginx/sites-enabled/rf-monitor
nginx -t
systemctl enable --now nginx
systemctl reload nginx

certificate_public_hash="$(openssl x509 -in "${tls_certificate}" -pubkey -noout | openssl pkey -pubin -outform DER | sha256sum | awk '{print $1}')"
key_public_hash="$(openssl pkey -in "${tls_key}" -pubout -outform DER | sha256sum | awk '{print $1}')"
[[ "${certificate_public_hash}" == "${key_public_hash}" ]] || die "TLS certificate and private key do not match."
if [[ -n "${ca_certificate}" ]]; then
  openssl verify -CAfile "${ca_certificate}" "${tls_certificate}" >/dev/null || die "Generated server certificate does not verify against the local CA."
  if systemctl is-active --quiet rf-monitor.service 2>/dev/null; then
    curl --fail --silent --show-error --cacert "${ca_certificate}" --resolve "${server_name}:443:${detected_ip}" "https://${server_name}/api/health" >/dev/null \
      || die "Nginx started, but the verified HTTPS health check failed."
  else
    echo "TLS and Nginx are ready. Application health will be checked during release activation."
  fi
  install -m 0644 -o root -g root "${ca_certificate}" /usr/local/share/ca-certificates/rf-monitor-local-ca.crt
  update-ca-certificates >/dev/null
fi

say "Ubuntu firewall"
echo "The safe rules allow SSH, allow HTTPS only from ${operator_cidr}, and block direct SDRconnect/Node access."
read -r -p "Apply and enable these UFW rules now? [Y/n]: " firewall_answer
if [[ ! "${firewall_answer:-Y}" =~ ^[Nn]$ ]]; then
  if ufw app info OpenSSH >/dev/null 2>&1; then
    ufw allow OpenSSH
  elif ss -H -ltn 2>/dev/null | awk '{print $4}' | grep -Eq '(^|:|\])22$'; then
    echo "An SSH listener was detected without a UFW profile; allowing TCP port 22."
    ufw allow 22/tcp
  else
    echo "No SSH server is installed or listening; no SSH firewall rule is needed."
  fi
  if [[ -n "${OPERATOR_CIDR:-}" && "${OPERATOR_CIDR}" != "${operator_cidr}" ]]; then
    ufw --force delete allow from "${OPERATOR_CIDR}" to any port 443 proto tcp >/dev/null 2>&1 || true
  fi
  ufw allow from "${operator_cidr}" to any port 443 proto tcp
  for sdr_port in "${local_sdr_ports[@]}"; do ufw deny "${sdr_port}/tcp"; done
  ufw deny "${backend_port}/tcp"
  ufw default deny incoming
  ufw --force enable
else
  echo "Firewall changes skipped. The dashboard is not production-ready until equivalent rules are applied."
fi

public_url="https://${server_name}/"
update_state PUBLIC_URL "${public_url}"
update_state OPERATOR_CIDR "${operator_cidr}"
update_state CA_CERTIFICATE "${ca_certificate}"
update_state TLS_CERTIFICATE "${tls_certificate}"
update_state TLS_PRIVATE_KEY "${tls_key}"

say "Secure dashboard configured"
echo "Dashboard: ${public_url}"
if [[ -n "${ca_certificate}" ]]; then
  echo "Local CA certificate: ${ca_certificate}"
  openssl x509 -in "${ca_certificate}" -noout -fingerprint -sha256
  echo
  echo "Create a fool-proof operator connection kit (replace USER):"
  echo "  sudo rf-monitor access --export /home/USER/Downloads"
  echo "Transfer the generated folder to each operator computer and follow START-HERE.txt."
else
  echo "The organization certificate was accepted. Operator computers must trust its issuing CA."
fi
echo "Show the dashboard address and connection checks with: sudo rf-monitor access"
echo "Check everything with: sudo rf-monitor doctor"
